function Get-NetInterfaceRegPaths {
    Get-NetAdapter -Physical | Where-Object { $_.Status -eq "Up" } | ForEach-Object {
        "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces\$($_.InterfaceGuid)"
    }
}

Get-NetInterfaceRegPaths | ForEach-Object {
    if (-not (Test-Path $_)) { New-Item $_ -Force | Out-Null }
    New-ItemProperty $_ TCPNoDelay -Value 1 -PropertyType DWord -Force
    New-ItemProperty $_ TcpAckFrequency -Value 1 -PropertyType DWord -Force
    New-ItemProperty $_ TcpDelAckTicks -Value 0 -PropertyType DWord -Force
}

